WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_essay_ending'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '豹尾收篇', 'kp-sl-essay-ending', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "大作文：豹尾收篇"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "总结全文，升华格局。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、万能结尾模板"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“（核心主题）是一项长期而艰巨的系统工程，绝非一朝一夕之功。站在新的历史起点上，我们只有（回顾分论点1），（回顾分论点2），（回顾分论点3），才能（解决面临的危机），最终书写（主题）的壮丽篇章，实现中华民族伟大复兴的宏伟蓝图！”"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "结尾一定要展现出公务员的宏观视野和对未来的必胜信念。"}]}]}$$ AS jsonb), NULL, '豹尾收篇的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "大作文", "豹尾结尾"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_essay_ending", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
